// =====================================================================
//  TRIAJE · resultado que recibe el workflow que pidió el triaje
// =====================================================================
const ruta = $('Preparar triaje').first().json.ruta;
if (ruta === 'no_existe') {
  return [{ json: { encontrada: false, clasificada: false, error: 'La incidencia no existe' } }];
}

const control = $('Validar clasificación').first().json;
const fila = $input.first().json;

return [
  {
    json: {
      encontrada: true,
      clasificada: control.clasificada,
      origen: control.origen,
      modelo: control.modelo ?? null,
      error: control.clasificada ? null : control.error,
      ajustes: control.ajustes ?? [],
      incidencia: fila.incidencia ?? null,
      efectos: control.clasificada
        ? {
            bloquea_espacio: fila.bloquea_espacio ?? false,
            bloquea_recurso: fila.bloquea_recurso ?? false,
            espacio: fila.espacio ?? null,
            recurso: fila.recurso ?? null,
            reservas_afectadas: fila.reservas_afectadas ?? [],
            cambios: fila.cambios ?? [],
          }
        : null,
    },
  },
];
